// A .d.ts-less CJS package that attaches its whole API as MEMBERS OF A
// FUNCTION — the namespace-object idiom handwritten CommonJS has used
// since before ES6 classes, and the shape every pbjs `--target
// static-module` bundle is built out of (`Message.encode = function(){}`).
//
// Nothing here is annotated, so each member's checker type is inference
// residue: `(text: any) => string[]`, not a mappable static type. That is
// the ONLY thing this package tests. Members of a module-level function
// are per-(symbol × key) module globals — one storage, whether the read
// spells the receiver as the local name inside this file or as the export
// table's member from the importer.
'use strict';

function parse(text) {
    return String(text).split(",");
}

// Data members: a mappable type (string, number) and later writes that
// widen the same slot.
parse.VERSION = "1.2.3";
parse.limit = 4;

// Function-valued members whose type is pure inference residue — the
// checked-dynamic per-piece fallback keeps their func-ness, so the calls
// below stay direct static calls.
parse.strict = function (text) {
    var parts = parse(text);
    if (parts.length > parse.limit) throw new Error("too many");
    return parts;
};

// A member READ from inside another member's body sees the live slot,
// including writes that happen textually after this function is defined.
parse.describe = function () {
    return "parse/" + parse.VERSION + " limit=" + parse.limit;
};

parse.limit = 2;

module.exports = { parse: parse };
